# Audit the narration audio pack (desktop\assets\narrations-audio.zip).
#
# The pack is generated by `go run ./cmd/audio-pack` from a database snapshot, and the
# desktop app unpacks it on first launch. This script checks the *archive artifact*:
#
#   1. manifest.json exists and declares every audio entry;
#   2. every target dir is well formed (<digits> for experiments, ms<digits> for milestones)
#      and matches the kind of narration the slug belongs to;
#   3. no two entries resolve to the same on-disk path (that would silently overwrite audio);
#   4. every entry's slug is known to the built-in narration scripts;
#   5. reports slug collisions (a slug that is both an experiment and a milestone).
#
# For "does the database have audio for every narration line", use the Go tool instead:
#   cd server && go run ./cmd/audioaudit -db <db> -audio <audio dir>
#
# Usage:
#   powershell -NoProfile -ExecutionPolicy Bypass -File tools/audit_narration_audio.ps1
[CmdletBinding()]
param(
    [string]$Zip = '',
    [string]$SeedDir = '',
    [int]$Sample = 40
)

$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem

if (-not $PSScriptRoot) { $PSScriptRoot = Split-Path -Parent $MyInvocation.MyCommand.Path }
$root = Resolve-Path (Join-Path $PSScriptRoot '..')
if (-not $Zip) { $Zip = Join-Path $root 'desktop\assets\narrations-audio.zip' }
if (-not $SeedDir) { $SeedDir = Join-Path $root 'server\internal\seed\data' }

if (-not (Test-Path $Zip)) {
    Write-Host ("audio pack not found: {0}" -f $Zip) -ForegroundColor Red
    exit 1
}

# ---- 1. built-in narration scripts: which slugs exist at all ----
$expSlugSet = @{}
$msSlugSet = @{}
Get-ChildItem $SeedDir -Filter 'narrations*.json' | ForEach-Object {
    $isMilestone = $_.Name -like 'narrations-ms*'
    $j = Get-Content $_.FullName -Raw -Encoding UTF8 | ConvertFrom-Json
    foreach ($p in $j.PSObject.Properties) {
        if ($isMilestone) { $msSlugSet[$p.Name] = $true } else { $expSlugSet[$p.Name] = $true }
    }
}
Write-Host ("built-in scripts : experiments {0} slugs / milestones {1} slugs" -f $expSlugSet.Count, $msSlugSet.Count)

# ---- 2. read the archive + manifest ----
$entries = New-Object System.Collections.ArrayList
$manifest = $null
$z = [System.IO.Compression.ZipFile]::OpenRead((Resolve-Path $Zip))
try {
    foreach ($e in $z.Entries) {
        if ($e.FullName -eq 'manifest.json') {
            $sr = New-Object System.IO.StreamReader($e.Open(), [System.Text.Encoding]::UTF8)
            try { $manifest = $sr.ReadToEnd() | ConvertFrom-Json } finally { $sr.Dispose() }
            continue
        }
        [void]$entries.Add($e.FullName)
    }
} finally { $z.Dispose() }

Write-Host ("archive          : {0} audio entries ({1:N1} MB)" -f $entries.Count, ((Get-Item $Zip).Length / 1MB))
if (-not $manifest) {
    Write-Host 'manifest.json MISSING: extraction would have to guess target dirs from the DB, which misplaces milestone audio' -ForegroundColor Red
    Write-Host 'AUDIT FAILED' -ForegroundColor Red
    exit 1
}

$manifestPaths = @{}
foreach ($m in $manifest.entries) { $manifestPaths[[string]$m.path] = [string]$m.dir }
$collisions = @()
if ($manifest.collisions) { $collisions = @($manifest.collisions) }
Write-Host ("manifest         : {0} entries / {1} slug collisions" -f @($manifest.entries).Count, $collisions.Count)

# ---- 3. per-entry checks ----
$undeclared = New-Object System.Collections.ArrayList
$badDirs = New-Object System.Collections.ArrayList
$dupTargets = New-Object System.Collections.ArrayList
$unknownSlug = New-Object System.Collections.ArrayList
$destSeen = @{}
$expDirs = @{}
$msDirs = @{}
$unknownSlugs = @{}

foreach ($e in $entries) {
    $parts = $e -split '/'
    $layoutOK = ($parts.Count -eq 3) -and ($parts[1] -eq 'yunxi' -or $parts[1] -eq 'xiaoxiao')
    if (-not $layoutOK) {
        [void]$badDirs.Add("bad entry layout: $e")
        continue
    }
    $slug = $parts[0]
    if (-not ($expSlugSet.ContainsKey($slug) -or $msSlugSet.ContainsKey($slug))) {
        if (-not $unknownSlugs.ContainsKey($slug)) {
            $unknownSlugs[$slug] = $true
            [void]$unknownSlug.Add($slug)
        }
    }
    if (-not $manifestPaths.ContainsKey([string]$e)) {
        [void]$undeclared.Add($e)
        continue
    }
    $dir = $manifestPaths[[string]$e]
    if ($dir -match '^ms[0-9]+$') {
        $msDirs[$dir] = $true
    } elseif ($dir -match '^[0-9]+$') {
        $expDirs[$dir] = $true
    } else {
        [void]$badDirs.Add("$e -> target dir '$dir'")
        continue
    }
    # 落盘文件名（去掉归档内的消歧前缀 <ms-id>.）
    $fileName = $parts[2]
    $prefix = "$dir."
    if ($fileName.StartsWith($prefix)) { $fileName = $fileName.Substring($prefix.Length) }
    $dest = "$dir/$($parts[1])/$fileName"
    if ($destSeen.ContainsKey($dest)) {
        [void]$dupTargets.Add("$dest <- $($destSeen[$dest]) and $e")
    } else {
        $destSeen[$dest] = $e
    }
}

# ---- report ----
function Show-List([string]$label, $items) {
    $color = 'Green'
    if ($items.Count -gt 0) { $color = 'Red' }
    Write-Host ("{0,-22}: {1}" -f $label, $items.Count) -ForegroundColor $color
    $i = 0
    foreach ($it in $items) {
        if ($i -ge $Sample) { Write-Host ("  ... {0} more" -f ($items.Count - $Sample)); break }
        Write-Host ("  - $it")
        $i++
    }
}

Write-Host ''
Write-Host ("on-disk targets  : {0} (experiment dirs {1} / milestone dirs {2})" -f $destSeen.Count, $expDirs.Count, $msDirs.Count)
Show-List 'UNDECLARED entries' $undeclared
Show-List 'BAD target dirs' $badDirs
Show-List 'DUPLICATE targets' $dupTargets
Show-List 'UNKNOWN slugs' $unknownSlug

Write-Host ''
Write-Host 'slug collisions (both experiment and milestone):' -ForegroundColor Cyan
if ($collisions.Count -eq 0) { Write-Host '  (none)' } else { $collisions | ForEach-Object { Write-Host ("  - " + $_) } }

$failed = ($undeclared.Count -gt 0) -or ($badDirs.Count -gt 0) -or ($dupTargets.Count -gt 0)

[pscustomobject]@{
    zip               = $Zip
    archive_entries   = $entries.Count
    on_disk_targets   = $destSeen.Count
    experiment_dirs   = $expDirs.Count
    milestone_dirs    = $msDirs.Count
    manifest_entries  = @($manifest.entries).Count
    seed_exp_slugs    = $expSlugSet.Count
    seed_ms_slugs     = $msSlugSet.Count
    archive_slugs     = ($expSlugSet.Count + $msSlugSet.Count)
    undeclared        = @($undeclared)
    bad_target_dirs   = @($badDirs)
    duplicate_targets = @($dupTargets)
    unknown_slugs     = @($unknownSlug)
    slug_collisions   = @($collisions)
    passed            = (-not $failed)
} | ConvertTo-Json -Depth 4 | Set-Content -Encoding UTF8 (Join-Path $PSScriptRoot 'narration-audit.json')

Write-Host ''
Write-Host ("report -> {0}" -f (Join-Path $PSScriptRoot 'narration-audit.json'))
if ($failed) {
    Write-Host 'AUDIT FAILED' -ForegroundColor Red
    exit 1
}
Write-Host 'AUDIT PASSED' -ForegroundColor Green
exit 0
